    Rocket, Flame, CheckCircle, Clock, Calendar,
    Users, Star, Trophy, Zap
} from 'lucide-react';
import axios from 'axios';

const Dashboard = () => {
    const { user, token } = useAuth();
    const [stats, setStats] = useState(null);
    const [loading, setLoading] = useState(true);
    const [weeklyData, setWeeklyData] = useState([]);

    useEffect(() => {
        if (user) {
            fetchStats();
            fetchWeeklyData();
        }
    }, [user]);

    const fetchStats = async () => {
        try {
            const response = await axios.get(
                `http://localhost:8081/api/tasks/user/${user.id}/progress`,
                { headers: { Authorization: `Bearer ${token}` } }
            );
            setStats(response.data);
            setLoading(false);
        } catch (error) {
            console.error('Failed to fetch stats:', error);
            setLoading(false);
        }
    };

    const fetchWeeklyData = async () => {
        try {
            const response = await axios.get(
                'http://localhost:8081/api/weekly',
                { headers: { Authorization: `Bearer ${token}` } }
            );
            setWeeklyData(response.data);
        } catch (error) {
            console.error('Failed to fetch weekly data:', error);
        }
    };

    if (loading) {
        return (
            <div className="flex items-center justify-center h-96">
                <div className="animate-spin rounded-full h-16 w-16 border-b-2 border-blue-600"></div>
            </div>
        );
    }

    // Calculate progress
    const totalDays = 120; // 4 months
    const completedDays = stats?.completedDays || 0;
    const completionRate = Math.round((completedDays / totalDays) * 100);
    const currentStreak = stats?.currentStreak || 0;

    // Generate contribution data (simulated)
    const generateContributions = () => {
        const data = [];
        const today = new Date();
        for (let i = 119; i >= 0; i--) {
            const date = new Date(today);
            date.setDate(date.getDate() - i);
            const day = date.getDate();
            const random = Math.random();
            let level = 0;
            if (random > 0.7) level = 4;
            else if (random > 0.5) level = 3;
            else if (random > 0.3) level = 2;
            else if (random > 0.1) level = 1;
            data.push({ date, level });
        }
        return data;
    };

    const contributions = generateContributions();

    const statsCards = [
        { 
            label: 'Overall Progress', 
            value: `${completionRate}%`, 
            icon: TrendingUp, 
            color: 'text-green-600',
            bg: 'bg-green-50'
        },
        { 
            label: 'Days Completed', 
            value: `${completedDays}/${totalDays}`, 
            icon: CalendarCheck, 
            color: 'text-blue-600',
            bg: 'bg-blue-50'
        },
        { 
            label: 'Current Streak', 
            value: `${currentStreak} days`, 
            icon: Flame, 
            color: 'text-orange-600',
            bg: 'bg-orange-50'
        },
        { 
            label: 'Monthly Target', 
            value: '30 days', 
            icon: Target, 
            color: 'text-purple-600',
            bg: 'bg-purple-50'
        },
    ];

    const weekColors = {
        1: 'border-blue-500 bg-blue-50',
        2: 'border-purple-500 bg-purple-50',
        3: 'border-green-500 bg-green-50',
        4: 'border-orange-500 bg-orange-50'
    };

    return (
        <div className="space-y-6">
            {/* Welcome Section */}
            <div className="bg-gradient-to-r from-blue-600 to-purple-600 rounded-2xl shadow-xl p-8 text-white">
                <div className="flex justify-between items-start">
                    <div>
                        <h1 className="text-3xl font-bold mb-2">
                            🚀 Welcome back, {user?.fullName || user?.username}!
                        </h1>
                        <p className="text-blue-100 text-lg">
                            You're on day {completedDays} of your 4-month journey
                        </p>
                        <div className="mt-4 flex gap-4">
                            <span className="px-3 py-1 bg-white/20 rounded-full text-sm flex items-center gap-2">
                                <Zap size={16} />
                                {currentStreak} day streak
                            </span>
                            <span className="px-3 py-1 bg-white/20 rounded-full text-sm flex items-center gap-2">
                                <Trophy size={16} />
                                {completionRate}% complete
                            </span>
                        </div>
                    </div>
                    <div className="text-right">
                        <div className="text-4xl font-bold">{completionRate}%</div>
                        <div className="text-sm text-blue-200">Overall Progress</div>
                    </div>
                </div>
            </div>

            {/* Stats Cards */}
            <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                {statsCards.map((stat, index) => {
                    const Icon = stat.icon;
                    return (
                        <div key={index} className={`${stat.bg} rounded-xl shadow-lg p-6 border border-gray-100`}>
                            <div className="flex items-center justify-between">
                                <div>
                                    <p className="text-sm text-gray-600">{stat.label}</p>
                                    <p className="text-2xl font-bold mt-1">{stat.value}</p>
                                </div>
                                <Icon className={`${stat.color} w-8 h-8`} />
                            </div>
                        </div>
                    );
                })}
            </div>

            {/* GitHub-Style Contribution Graph */}
            <div className="bg-white rounded-xl shadow-lg p-6">
                <h2 className="text-lg font-semibold mb-4 flex items-center gap-2">
                    <GitBranch className="text-gray-600" size={20} />
                    Daily Activity (Last 4 Months)
                </h2>
                <div className="overflow-x-auto">
                    <div className="min-w-[700px]">
                        <div className="grid grid-cols-[repeat(53,1fr)] gap-1">
                            {contributions.map((day, index) => {
                                const colors = {
                                    0: 'bg-gray-100',
                                    1: 'bg-green-200',
                                    2: 'bg-green-300',
                                    3: 'bg-green-400',
                                    4: 'bg-green-600'
                                };
                                return (
                                    <div
                                        key={index}
                                        className={`w-3 h-3 rounded-sm ${colors[day.level]}`}
                                        title={`${day.date.toDateString()}: ${day.level} tasks`}
                                    ></div>
                                );
                            })}
                        </div>
                        <div className="flex justify-between mt-2 text-xs text-gray-500">
                            <span>Nov 2025</span>
                            <span>Feb 2026</span>
                        </div>
                    </div>
                </div>
                <div className="mt-4 flex items-center gap-2 text-xs text-gray-500">
                    <span>Less</span>
                    <div className="flex gap-1">
                        <div className="w-3 h-3 bg-gray-100 rounded-sm"></div>
                        <div className="w-3 h-3 bg-green-200 rounded-sm"></div>
                        <div className="w-3 h-3 bg-green-300 rounded-sm"></div>
                        <div className="w-3 h-3 bg-green-400 rounded-sm"></div>
                        <div className="w-3 h-3 bg-green-600 rounded-sm"></div>
                    </div>
                    <span>More</span>
                </div>
            </div>

            {/* Weekly Focus Areas */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                {weeklyData.map((week) => (
                    <div
                        key={week.week}
                        className={`border-l-4 rounded-xl p-5 shadow-md ${weekColors[week.week] || 'border-gray-300 bg-gray-50'}`}
                    >
                        <h3 className="text-xl font-bold mb-3 flex items-center gap-2">
                            <Rocket size={20} className="text-purple-600" />
                            Week {week.week}
                        </h3>
                        <div className="space-y-3">
                            <div className="flex items-start gap-2">
                                <BookOpen size={16} className="text-blue-600 mt-1" />
                                <div>
                                    <span className="font-semibold">Java:</span>
                                    <span className="ml-2 text-gray-700">{week.java}</span>
                                </div>
                            </div>
                            <div className="flex items-start gap-2">
                                <Code2 size={16} className="text-green-600 mt-1" />
                                <div>
                                    <span className="font-semibold">DSA:</span>
                                    <span className="ml-2 text-gray-700">{week.leetcodeDsa}</span>
                                </div>
                            </div>
                            <div className="flex items-start gap-2">
                                <Database size={16} className="text-purple-600 mt-1" />
                                <div>
                                    <span className="font-semibold">Projects:</span>
                                    <span className="ml-2 text-gray-700">{week.projects}</span>
                                </div>
                            </div>
                            <div className="flex items-start gap-2">
                                <Server size={16} className="text-orange-600 mt-1" />
                                <div>
                                    <span className="font-semibold">Other:</span>
                                    <span className="ml-2 text-gray-700">{week.other}</span>
                                </div>
                            </div>
                        </div>
                        <div className="mt-3 pt-3 border-t border-gray-200">
                            <div className="flex items-center justify-between text-sm">
                                <span className="text-gray-500">Progress</span>
                                <span className="font-semibold text-blue-600">
                                    {Math.min(100, (week.week / 4) * 100)}%
                                </span>
                            </div>
                            <div className="w-full bg-gray-200 rounded-full h-2 mt-1">
                                <div 
                                    className="bg-blue-600 rounded-full h-2 transition-all"
                                    style={{ width: `${Math.min(100, (week.week / 4) * 100)}%` }}
                                ></div>
                            </div>
                        </div>
                    </div>
                ))}
            </div>

            {/* Motivation Section */}
            <div className="bg-gradient-to-r from-pink-500 to-orange-500 rounded-xl shadow-lg p-6 text-white">
                <div className="flex items-center justify-between flex-wrap">
                    <div>
                        <h3 className="text-xl font-bold">💪 Stay Consistent!</h3>
                        <p className="text-pink-100">Remember: 1% better every day = 37x better in a year</p>
                    </div>
                    <div className="flex gap-4 flex-wrap mt-2 md:mt-0">
                        <span className="px-3 py-1 bg-white/20 rounded-full text-sm">#NoZeroDays</span>
                        <span className="px-3 py-1 bg-white/20 rounded-full text-sm">#CodeEveryday</span>
                        <span className="px-3 py-1 bg-white/20 rounded-full text-sm">#NeverGiveUp</span>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default Dashboard;
